	public function calculate_final_price_from_xml( float $base_price, float $personal_price, string $normalized_brand, array $cat_slugs ): array {

		// 1) Pritaikom supplier discount
		$supplier_discount = $this->get_supplier_discount( $normalized_brand );
		// v1.7.0: VF akcija ($base_price kai base<personal) JAU YRA supplier discount.
		//   Antras taikymas cia = dvigubinimas. Tik personal gauna supplier_discount.
		//   Kai VF neturi akcijos ($base = $personal), rezultatas nepakinta,
		//   nes real_base tik naudojamas skaiciuojant sale, kuris tampa 0 sale-clear
		//   saugikliu (real_base >= real_personal reiskia jokios akcijos).
		$real_base     = $base_price;
		$real_personal = $personal_price * ( 1 - $supplier_discount );

		// 2) Markup
		$markup_info = $this->get_markup( $normalized_brand, $cat_slugs );
		$markup = $markup_info['markup'];
		$rule = $markup_info['rule'];
		if ( $supplier_discount > 0 ) {
			$rule .= ' +DISC:' . round( $supplier_discount * 100 ) . '%';
		}

		// 3) Regular price = personal x markup x VAT
		// Jei personal nera (0), naudojam base kaip fallback
		$cost_for_regular = $real_personal > 0 ? $real_personal : $real_base;
		$regular_calculated = $cost_for_regular * ( 1 + $markup ) * self::VAT;
